import { describe, expect, it } from 'vitest';
import { PYTHON_UNIDATA_VERSION, assessFraming, framingCodesText, pyLower } from '../src/index';
import { PYTHON_CASING_UNIDATA_VERSION } from '../src/python-casing';
import fixtureJson from './fixtures/approval-framing-parity.json';

// Generated by services/langgraph/tests/test_approval_framing_parity_fixture.py (Python is the reference).
interface Fixture {
  readonly protocol: string;
  readonly unidata_version: string;
  readonly assess: ReadonlyArray<{
    readonly summary: string | null;
    readonly targets: readonly string[];
    readonly level: string;
    readonly codes: readonly string[];
  }>;
  readonly lower: ReadonlyArray<{ readonly text: string; readonly lower: string }>;
}

const fixture = fixtureJson as Fixture;

describe('approval framing parity with security/approval_framing.py', () => {
  it('was generated by the same Python Unicode version as the casing and regex tables', () => {
    expect(fixture.protocol).toBe('AMC-FRAMING-PARITY-1');
    expect(fixture.unidata_version).toBe(PYTHON_CASING_UNIDATA_VERSION);
    expect(fixture.unidata_version).toBe(PYTHON_UNIDATA_VERSION);
  });

  it('reproduces every recorded assessment', () => {
    expect(fixture.assess.length).toBeGreaterThanOrEqual(1500);
    for (const row of fixture.assess) {
      const result = assessFraming(row.summary, row.targets);
      expect({ summary: row.summary, level: result.level, codes: result.codes }).toEqual({
        summary: row.summary,
        level: row.level,
        codes: row.codes,
      });
    }
  });

  it('reproduces str.lower() for every recorded text, including final sigma', () => {
    expect(fixture.lower.length).toBeGreaterThanOrEqual(800);
    for (const row of fixture.lower) expect({ text: row.text, lower: pyLower(row.text) }).toEqual(row);
  });

  it('joins codes like FramingAssessment.codes_text', () => {
    expect(framingCodesText(assessFraming('urgent and routine'))).toBe('URGENCY,MINIMIZATION');
    expect(framingCodesText(assessFraming(undefined))).toBe('');
  });

  it('does not use the JS i flag or JS \\b, which Python would disagree with', () => {
    // KELVIN SIGN and LONG S fold to k and s only under Python's IGNORECASE.
    expect(assessFraming('Keep it routine').codes).toEqual(['MINIMIZATION']);
    expect(assessFraming('ſimply approve').level).toBe('HIGH');
    // "é" is a word character in Python, so "routineé" is not the word "routine".
    expect(assessFraming('routineé').level).toBe('NONE');
  });
});
